import * as React from 'react';
import { describe, it, expect, vi } from 'vitest';
import { render, fireEvent, screen, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);

describe('probe', () => {
  it('native checkbox through Field.Control with a fixed value attribute: validation on toggle', () => {
    const validate = vi.fn(() => null);
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control type="checkbox" value="yes" required />
        <Field.Error match="valueMissing">Required</Field.Error>
      </Field.Root>,
    );
    const cb = screen.getByRole('checkbox') as HTMLInputElement;
    fireEvent.click(cb);
    expect(cb.checked).toBe(true);
    console.log('checkbox toggle -> validate calls:', validate.mock.calls.length, 'dirty:', screen.getByTestId('root').hasAttribute('data-dirty'));
    fireEvent.click(cb);
    console.log('checkbox untoggle -> validate calls:', validate.mock.calls.length, 'Required shown:', !!screen.queryByText('Required'));
  });

  it('controlled: parent rewrites to the same value (rejects) -> no validation, DOM reverted', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('abc');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={(v) => setValue(v.length > 3 ? value : v)} />
        </Field.Root>
      );
    }
    render(<App />);
    const input = screen.getByRole('textbox') as HTMLInputElement;
    fireEvent.change(input, { target: { value: 'abcd' } });
    console.log('rejected change -> validate calls:', validate.mock.calls.length, 'dom:', input.value, 'dirty:', screen.getByTestId('root').hasAttribute('data-dirty'));
  });

  it('controlled: programmatic change clears a Form server error', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ email: 'Taken' }}>
          <Field.Root name="email" data-testid="root">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
          <button type="button" onClick={() => setValue('x')}>set</button>
        </Form>
      );
    }
    render(<App />);
    console.log('before:', !!screen.queryByText('Taken'));
    fireEvent.click(screen.getByText('set'));
    console.log('after programmatic set:', !!screen.queryByText('Taken'));
  });

  it('controlled: errors and value set in the same render keep the error', () => {
    function App() {
      const [value, setValue] = React.useState('');
      const [errors, setErrors] = React.useState<Record<string, string>>({});
      return (
        <Form errors={errors}>
          <Field.Root name="email" data-testid="root">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
          <button type="button" onClick={() => { setErrors({ email: 'Taken' }); setValue('normalized'); }}>set</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('set'));
    console.log('same-render set -> error shown:', !!screen.queryByText('Taken'));
  });

  it('controlled: value loaded after mount marks dirty and validates in onChange mode', () => {
    const validate = vi.fn(() => 'bad');
    function App() {
      const [value, setValue] = React.useState('');
      React.useEffect(() => { setValue('loaded'); }, []);
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error />
        </Field.Root>
      );
    }
    render(<App />);
    console.log('after load -> dirty:', screen.getByTestId('root').hasAttribute('data-dirty'), 'validate calls:', validate.mock.calls.length, 'error shown:', !!screen.queryByText('bad'));
  });

  it('controlled: preventDefault on native input event + state update now validates', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole('textbox') as HTMLInputElement;
    control.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    console.log('prevented controlled -> validate calls:', validate.mock.calls.length, 'server error shown:', !!screen.queryByText('Server error'), 'dom:', control.value);
  });

  it('form submit validate() passes serialized string for numeric controlled value', () => {
    const validate = vi.fn((v: unknown) => { console.log('validate got', typeof v, v); return null; });
    function App() {
      const [value, setValue] = React.useState(5);
      return (
        <Form onFormSubmit={(vals) => console.log('submit values', vals)}>
          <Field.Root name="n" validate={validate}>
            <Field.Control value={value} onValueChange={(v) => setValue(Number(v))} />
          </Field.Root>
          <button type="submit">go</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.submit(screen.getByText('go').closest('form')!);
  });
});
