  });

  it('required native checkbox WITHOUT value attr: error clears after checking post-submit', () => {
    render(
      <Form>
        <Field.Root name="terms" data-testid="root">
          <Field.Control type="checkbox" required />
          <Field.Error match="valueMissing">Required</Field.Error>
        </Field.Root>
        <button type="submit">go</button>
      </Form>,
    );
    const cb = screen.getByRole('checkbox') as HTMLInputElement;
    fireEvent.submit(screen.getByText('go').closest('form')!);
    console.log('[novalue] after submit -> Required shown:', !!screen.queryByText('Required'));
    fireEvent.click(cb);
    console.log('[novalue] after check -> checked:', cb.checked, 'Required shown:', !!screen.queryByText('Required'), 'aria-invalid:', cb.getAttribute('aria-invalid'));
  });

  it('controlled checkbox (checked + value) in onChange mode with Field.Error', () => {
    function App() {
      const [checked, setChecked] = React.useState(false);
      return (
        <Field.Root name="terms" data-testid="root" validationMode="onChange">
          <Field.Control type="checkbox" value="yes" required checked={checked} onChange={(e) => setChecked(e.target.checked)} />
          <Field.Error match="valueMissing">Required</Field.Error>
        </Field.Root>
      );
    }
    render(<App />);
    const cb = screen.getByRole('checkbox') as HTMLInputElement;
    fireEvent.click(cb);
    fireEvent.click(cb);
    console.log('[controlled checked] after check+uncheck -> checked:', cb.checked, 'Required shown:', !!screen.queryByText('Required'), 'dirty:', screen.getByTestId('root').hasAttribute('data-dirty'));
  });
});
